function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 400) return 'nums needs 2 to 400 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 127)) return 'Each value is an integer from 1 to 127.';
  if (!Number.isInteger(k) || k < 1 || 2 * k > nums.length) return 'k is between 1 and nums.length / 2.';
  return null;
}

