function maxValue(nums, k) {
  const n = nums.length;

  function firstReach(list) {
    const seen = [];
    const values = [];
    for (let j = 0; j <= k; j++) {
      seen.push(new Array(128).fill(false));
      values.push([]);
    }
    seen[0][0] = true;
    values[0].push(0);
    const found = [];
    for (let p = 0; p < list.length; p++) {
      const x = list[p];
      const low = Math.max(1, k - (list.length - 1 - p));
      for (let j = Math.min(k, p + 1); j >= low; j--) {
        const from = values[j - 1];
        for (let t = 0; t < from.length; t++) {
          const next = from[t] | x;
          if (!seen[j][next]) {
            seen[j][next] = true;
            values[j].push(next);
            if (j === k) {
              found.push([next, p]);
            }
          }
        }
      }
    }
    return found;
  }

  const left = firstReach(nums);
  const right = firstReach([...nums].reverse());
  let best = 0;
  for (const [a, end] of left) {
    for (const [b, back] of right) {
      if (end < n - 1 - back) {
        best = Math.max(best, a ^ b);
      }
    }
  }
  return best;
}

