function maxValue(nums, k) {
  // Try every subsequence of 2k elements and evaluate it directly.
  let best = 0;
  const picked = [];
  function choose(from) {
    if (picked.length === 2 * k) {
      let first = 0;
      let second = 0;
      for (let t = 0; t < k; t++) first |= picked[t];
      for (let t = k; t < 2 * k; t++) second |= picked[t];
      best = Math.max(best, first ^ second);
      return;
    }
    for (let i = from; i <= nums.length - (2 * k - picked.length); i++) {
      picked.push(nums[i]);
      choose(i + 1);
      picked.pop();
    }
  }
  choose(0);
  return best;
}

