function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 340 + Math.floor(rand() * 61) : 2 + Math.floor(rand() * 11);
  const shape = rand();
  let nums;
  if (shape < 0.2) nums = Array.from({ length: n }, () => 1 << Math.floor(rand() * 7));
  else if (shape < 0.4) nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 7));
  else if (shape < 0.5) { const v = 1 + Math.floor(rand() * 127); nums = Array.from({ length: n }, () => (rand() < 0.8 ? v : 1 + Math.floor(rand() * 127))); }
  else nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 127));
  const k = 1 + Math.floor(rand() * Math.floor(n / 2));
  return [nums, k];
}
